<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import MaterialReader from '../../../shared/MaterialReader.vue';
import { courseFlow as flow } from '../course-flow';
import { chapterReady, lessonFeedback } from '../../../shared/learning-flow';
const props=defineProps<{spaceId:string;page:string}>();
const emit=defineEmits<{start:[chapterId:string,mode:'lesson'|'test'];resume:[activityId:string]}>();
const space=computed(()=>flow.spaces.find(s=>s.id===props.spaceId));
const course=computed(()=>flow.courses.find(c=>c.id===space.value?.courseId));
const query=ref(''),source=ref(''),expanded=ref(''),openActivity=ref(''),reading=ref('');
const chapters=computed(()=>course.value?.snapshot.book.units.flatMap(u=>u.chapters)||[]);
const activities=computed(()=>flow.lessons.filter(a=>a.spaceId===props.spaceId).slice().reverse());
const requirements=computed(()=>course.value?.snapshot.target.claims.flatMap(c=>c.requirements)||[]);
const errors=computed(()=>flow.uses.filter(u=>u.spaceId===props.spaceId&&u.result==='错误'&&(!source.value||u.purpose===source.value)));
const last=computed(()=>activities.value[0]);
const openUnits=ref<string[]>([]);
watch(()=>course.value?.id,()=>{openUnits.value=course.value?.snapshot.book.units.slice(0,1).map(u=>u.id)||[];},{immediate:true});
function toggleUnit(id:string){openUnits.value=openUnits.value.includes(id)?openUnits.value.filter(x=>x!==id):[...openUnits.value,id];}
const title=computed(()=>({home:'首页',textbook:'教材',status:'学习情况',errorbook:'错题本'}[props.page]));
function ready(id:string){return chapterReady(course.value!.snapshot,id);}
function chapterName(id:string){return chapters.value.find(ch=>ch.id===id)?.name||id;}
</script>
<template><div v-if="course&&space" class="course-page">
  <header class="page-header"><div><h2>{{title}}</h2><p>{{course.snapshot.book.name}}</p></div><span class="mock-tag">Mock 联动预览</span></header>
  <template v-if="page==='textbook'"><details class="course-definition"><summary>当前学习目标：{{course.snapshot.target.name}}</summary><p>{{course.snapshot.target.description}}</p><p>教材 v{{course.snapshot.book.revision}} · 目标 v{{course.snapshot.target.revision}} · 管理员应用于 {{course.appliedAt}}</p><p>教材和目标由管理员维护，你可以在每次学习时选择章节。</p></details><label class="search">查找章节<input v-model="query" placeholder="输入章节名称" type="search"/></label>
    <section v-for="unit in course.snapshot.book.units.filter(u=>u.chapters.some(c=>c.name.includes(query)))" :key="unit.id" class="unit"><button class="chapter-toggle" :aria-expanded="openUnits.includes(unit.id)||!!query" @click="toggleUnit(unit.id)"><h3>{{unit.name}}</h3><span>{{openUnits.includes(unit.id)?'−':'＋'}}</span></button><article v-for="ch in (openUnits.includes(unit.id)||query?unit.chapters.filter(c=>c.name.includes(query)):[])" :key="ch.id" class="chapter-row"><div><h4>{{ch.name}}</h4><p>{{ready(ch.id).reason||'讲解与检测依据已准备'}}</p><small v-if="!ready(ch.id).scripted">此章暂未编写 mock 对话样例</small></div><div class="actions"><button v-if="ch.items?.some(i=>i.reviewed)" @click="reading=reading===ch.id?'':ch.id">{{reading===ch.id?'收起材料':'查看本课材料'}}</button><button :disabled="!ready(ch.id).explain||!ready(ch.id).scripted" @click="emit('start',ch.id,'lesson')">讲解</button><button :disabled="!ready(ch.id).test||!ready(ch.id).scripted" @click="emit('start',ch.id,'test')">检测</button></div></article><MaterialReader v-if="reading&&unit.chapters.some(c=>c.id===reading)" :key="reading" :related-items="chapters.flatMap(c=>c.items||[]).filter(i=>i.reviewed)" :items="unit.chapters.find(c=>c.id===reading)!.items!.filter(i=>i.reviewed)"/></section>
  </template>
  <template v-else-if="page==='status'"><p class="lead">按章节查看学习要求及其依据。做过几道题与是否达标分别记录。</p><section v-for="ch in chapters.filter(ch=>requirements.some(r=>r.chapterIds.includes(ch.id)))" :key="ch.id" class="unit"><button class="chapter-toggle" :aria-expanded="expanded===ch.id" @click="expanded=expanded===ch.id?'':ch.id"><strong>{{ch.name}}</strong><span>{{requirements.filter(r=>r.chapterIds.includes(ch.id)).length}} 项要求待确认 {{expanded===ch.id?'−':'＋'}}</span></button><div v-if="expanded===ch.id"><article v-for="r in requirements.filter(r=>r.chapterIds.includes(ch.id))" :key="r.id" class="requirement"><div><strong>{{r.name}}</strong><span class="status">待确认</span></div><details><summary>查看要求说明</summary><p>{{r.standard.replace(/Claim/g,'本项要求')}}</p></details><p class="note">{{activities.some(a=>a.chapterId===ch.id)?'已有当堂记录；本轮未运行正式能力推断，不据此宣称达标。':'尚无学习表现依据，不代表不会。'}}</p><button v-if="activities.find(a=>a.chapterId===ch.id)" @click="openActivity=activities.find(a=>a.chapterId===ch.id)!.id">查看依据</button></article></div></section>
  </template>
  <template v-else-if="page==='errorbook'"><p class="lead">{{errors.length}} 条错误作答记录 · 讲解和订正不直接代表已掌握</p><label class="search">来源<select v-model="source"><option value="">全部来源</option><option>练习</option><option>检测</option></select></label><article v-for="u in errors" :key="u.id" class="unit"><span class="status">{{u.purpose}}</span><h3>{{u.question.question}}</h3><p>原作答：{{u.answer}}</p><p class="note">{{u.help}}</p><button @click="openActivity=u.activityId">查看学习记录</button><button @click="emit('resume',u.activityId)">继续讲解</button></article><p v-if="!errors.length" class="empty">暂无确认错误的作答。未作答或尚未判定的题目不计入错题。</p></template>
  <template v-else><section class="unit"><h3>{{last?'继续上次学习':'开始学习'}}</h3><template v-if="last"><p>{{chapterName(last.chapterId)}} · {{last.stage==='finished'?'已结束，可回看':'进度已保存'}}</p><button class="primary" @click="emit('resume',last.id)">{{last.stage==='finished'?'查看上次学习':'继续学习'}}</button></template><template v-else><p>空间已经建立。选择教材章节开始，当前尚无个人学习判断。</p><button v-for="ch in chapters.filter(ch=>ready(ch.id).explain&&ready(ch.id).scripted).slice(0,1)" :key="ch.id" class="primary" @click="emit('start',ch.id,'lesson')">学习：{{ch.name}}</button></template></section><section class="unit"><h3>最近学习</h3><article v-for="a in activities.slice(0,5)" :key="a.id" class="chapter-row"><div>{{chapterName(a.chapterId)}}<p class="note">{{a.at}} · {{a.stage==='finished'?a.endReason:'进行中'}}</p></div><button @click="openActivity=a.id">查看记录</button></article><p v-if="!activities.length" class="empty">还没有学习记录。</p></section></template>
  <section v-if="openActivity&&activities.find(a=>a.id===openActivity)" class="unit activity-record"><div class="chapter-toggle"><h3>学习记录</h3><button @click="openActivity=''">收起记录</button></div><p>{{lessonFeedback(flow,activities.find(a=>a.id===openActivity)!).summary}}</p><article v-for="u in flow.uses.filter(u=>u.activityId===openActivity)" :key="u.id" class="past-answer"><strong>{{u.purpose}} · {{u.question.question}}</strong><p>原作答：{{u.answer||'未提交'}} · {{u.result||'未判定'}}</p><p class="note">{{u.help}}</p></article><button class="primary" @click="emit('resume',openActivity)">回到原对话</button></section>
</div></template>
<style scoped>
.course-page{padding:28px 32px;max-width:1100px;margin:auto;color:#2c3e50}.page-header{display:flex;justify-content:space-between;gap:16px;align-items:start;margin-bottom:24px}h2{font-size:24px;margin:0 0 8px}h3{font-size:17px;margin:0 0 12px}h4{margin:0 0 8px;font-size:15px}.page-header p,.note,small{color:#75857c;font-size:13px}.mock-tag{font-size:12px;white-space:nowrap;color:#7b8980}.unit,.course-definition{border:1px solid #dce5df;background:#fff;border-radius:10px;padding:20px;margin-bottom:18px}.chapter-row{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:18px 0;border-top:1px solid #edf1ee}.chapter-row p{font-size:13px;margin:6px 0}.chapter-row:first-of-type{border-top:0}.actions{display:flex;gap:8px;flex-shrink:0}button{font:inherit;padding:8px 14px;border:1px solid #d5dfd8;border-radius:6px;background:white;color:#2d6a4f;cursor:pointer}button:disabled{opacity:.45;cursor:default}.primary{background:#2d6a4f;color:white}.search{display:block;margin:18px 0;font-size:13px}.search input,.search select{margin-left:12px;padding:8px;border:1px solid #d5dfd8;border-radius:6px}.chapter-toggle{display:flex;justify-content:space-between;align-items:center;width:100%;border:0;text-align:left;background:none;padding:0;gap:14px}.chapter-toggle span{font-size:13px;color:#7a877e}.requirement,.past-answer{border-top:1px solid #e4ece6;margin-top:18px;padding-top:16px}.requirement p,p{line-height:1.8}.status{display:inline-block;margin-left:12px;background:#f3f5f2;color:#7a806d;border-radius:4px;padding:3px 8px;font-size:12px}.empty{color:#86948b}.lead{font-size:14px;line-height:1.8}summary{cursor:pointer}@media(max-width:800px){.course-page{padding:20px 16px}.chapter-row{align-items:start;flex-wrap:wrap}.page-header{flex-wrap:wrap}.chapter-toggle{flex-wrap:wrap}}
</style>
